//! # Legacy protocol translation
//!
//! Two independent concerns, both keyed off the client's [`MinecraftVersion`]:
//!
//! - [`ids`] rewrites the packet id `VarInt` between the native numbering and a legacy
//!   client's numbering, from matrices generated by `steel-registry`.
//! - [`payload`] rewrites fields whose *wire layout* changed within the supported range.
//!
//! The id rewrite happens before framing and compression (see
//! [`crate::packet_traits::ClientPacket::write_packet_for`]), the only point where it is
//! still possible, and the payload rewrite happens alongside it.
//!
//! Fields that changed *outside* the 1.21–26.3 range are deliberately absent here: block
//! position X/Z order changed in 1.14 and chat components moved from JSON to NBT in 1.20.3,
//! so every supported client already sees the native form of both.

pub mod ids;
pub mod payload;

pub use ids::{column_for, current_column, remap_clientbound, remap_serverbound, translation_for};
pub use payload::{
    read_bit_set_legacy, read_container_id_legacy, read_velocity_legacy, write_bit_set_legacy,
    write_container_id_legacy, write_velocity_legacy,
};

use crate::version::MinecraftVersion;

/// Whether the payload adapters cover every wire difference of `version`.
///
/// Enablement point for [`MinecraftVersion::is_translatable`]: a legacy client is admitted
/// only once both its packet-id matrix and its payload layout are actually implemented, so
/// that it never receives a packet it cannot parse.
///
/// A version is only reported ready once every packet carrying a field that differs on it
/// overrides `write_payload_legacy`/`read_payload_legacy`; until that override lands the
/// client would receive a native-layout payload under a translated id.
#[must_use]
pub const fn payload_adapters_ready(version: MinecraftVersion) -> bool {
    version.is_current()
}
